import java.util.*;

public class Solution {
    static int componentes(int n, int[][] arestas) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : arestas) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        boolean[] visto = new boolean[n];
        int total = 0;
        ArrayDeque<Integer> pilha = new ArrayDeque<>();
        for (int s = 0; s < n; s++) {
            if (visto[s]) continue;
            total++;
            visto[s] = true;
            pilha.push(s);
            while (!pilha.isEmpty()) {
                int u = pilha.pop();
                for (int v : adj.get(u)) {
                    if (!visto[v]) {
                        visto[v] = true;
                        pilha.push(v);
                    }
                }
            }
        }
        return total;
    }
}

