        assertEquals(2, Solution.componentes(5, new int[][]{{0, 1}, {1, 2}, {3, 4}}));
        assertEquals(5, Solution.componentes(5, new int[][]{}));
        assertEquals(1, Solution.componentes(3, new int[][]{{0, 1}, {1, 2}, {2, 0}}));
    }

    @Test void lacosEArestasRepetidas() {
        assertEquals(2, Solution.componentes(3, new int[][]{{0, 0}, {1, 2}, {2, 1}}));
    }

    @Test void caminhoGigante() {
        int n = 200_000;
        int[][] e = new int[n - 1][];
        for (int i = 0; i + 1 < n; i++) e[i] = new int[]{i, i + 1};
        assertEquals(1, Solution.componentes(n, e));
    }
}

