import java.util.*;

public class Solution {
    private static final int BRANCO = 0, CINZA = 1, PRETO = 2;

    static boolean temCiclo(int n, int[][] arestas) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : arestas) adj.get(e[0]).add(e[1]);
        int[] cor = new int[n];
        for (int s = 0; s < n; s++) if (cor[s] == BRANCO && dfs(s, adj, cor)) return true;
        return false;
    }

    // Cinza = ainda na pilha de recursão. Aresta para cinza = aresta de retorno = ciclo.
    private static boolean dfs(int u, List<List<Integer>> adj, int[] cor) {
        cor[u] = CINZA;
        for (int v : adj.get(u)) {
            if (cor[v] == CINZA) return true;
            if (cor[v] == BRANCO && dfs(v, adj, cor)) return true;
        }
        cor[u] = PRETO;
        return false;
    }
}

