import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void comCiclo() {
        assertTrue(Solution.temCiclo(3, new int[][]{{0, 1}, {1, 2}, {2, 0}}));
        assertTrue(Solution.temCiclo(1, new int[][]{{0, 0}}));
    }

    @Test void diamanteNaoEhCiclo() {
        // 0→1, 0→2, 1→3, 2→3: o 3 é revisitado já preto, não cinza.
        assertFalse(Solution.temCiclo(4, new int[][]{{0, 1}, {0, 2}, {1, 3}, {2, 3}}));
    }

    @Test void desconexo() {
        assertFalse(Solution.temCiclo(4, new int[][]{{0, 1}, {2, 3}}));
        assertTrue(Solution.temCiclo(5, new int[][]{{0, 1}, {2, 3}, {3, 4}, {4, 2}}));
    }

    @Test void arestaDeIdaEVolta() {
        assertTrue(Solution.temCiclo(2, new int[][]{{0, 1}, {1, 0}}));
    }
}
